<script setup lang="ts">
import { ref } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import { BASE, getToken, request } from '../../api'
import { money, orderTime, orderStatus, type Order, type OrderPage, type Review } from '../../../../shared/orders'
const orders = ref<Order[]>([]), total = ref(0), page = ref(0), busy = ref(false), error = ref(''), selected = ref<Order | null>(null)
const reason = ref(''), reviews = ref<Record<number,{rating:string;content:string}>>({})
async function run(action: () => Promise<void>) { if(busy.value) return; busy.value=true; error.value='';try { await action() } catch(e) { error.value=e instanceof Error ? e.message:'操作失败' } finally { busy.value=false } }
async function load(reset=true) { const next=reset ? 1:page.value+1; const result=await request<OrderPage>('/orders?page='+next);orders.value=reset ? result.items:[...orders.value,...result.items];total.value=result.total;page.value=next; if(selected.value) selected.value=await request<Order>('/orders/'+selected.value.id) }
onShow(() => { if(!getToken()) { uni.navigateTo({url:'/pages/login/index'});error.value='请先登录后刷新订单';return };run(()=>load()) })
function detail(o: Order) { return run(async()=>{ selected.value=await request<Order>('/orders/'+o.id);reason.value='';for(const item of selected.value.items) reviews.value[item.id]={rating:'5',content:''} }) }
function action(name: string) { const o=selected.value;if(!o)return;uni.showModal({title:name==='RECEIVE'?'确认收货':'取消模拟订单',content:name==='RECEIVE'?'确认后可评价订单商品。':'取消后会释放库存。',success:r=>{if(r.confirm)run(async()=>{selected.value=await request<Order>('/orders/'+o.id+'/actions','POST',{version:o.version,action:name,reason:reason.value});await load()})}}) }
function review(id: number) { return run(async()=>{ const input=reviews.value[id];await request<Review>('/order-items/'+id+'/review','POST',{rating:Number(input.rating),content:input.content});selected.value=await request<Order>('/orders/'+selected.value!.id) }) }
function preview(fileId: number) { uni.downloadFile({url:BASE+'/api/v1/files/'+fileId+'/content',header:{Authorization:'Bearer '+getToken()},success:r=>{ if(r.statusCode===200) uni.previewImage({urls:[r.tempFilePath]});else error.value='无权访问或图片不存在' },fail:()=>{error.value='图片加载失败'}}) }
</script>
<template><view class="screen"><view class="top"><text class="title">我的订单</text><button size="mini" :disabled="busy" @click="run(()=>load())">刷新</button></view><text class="notice">模拟履约 · 无真实支付</text><view v-if="error" class="error">{{ error }}</view>
<view v-if="selected" class="card"><button class="secondary" @click="selected=null">返回订单列表</button><text class="heading">{{ orderStatus(selected.status) }} · ¥ {{ money(selected.total_amount) }}</text><text>{{ selected.order_no }}</text><text>{{ selected.shop_name }}</text><text>收货人：{{ selected.address_snapshot.recipient }} {{ selected.address_snapshot.phone }}<br/>{{ selected.address_snapshot.address }}</text>
<view v-for="item in selected.items" :key="item.id" class="line"><text class="heading">{{ item.product_name }}</text><text>{{ item.sku_code }} · ¥ {{ money(item.unit_price) }} × {{ item.quantity }} {{ item.unit }}</text><text>{{ Object.values(item.specification).filter(Boolean).join(' · ') }}</text><button v-if="item.cover_file_id" size="mini" class="secondary" @click="preview(item.cover_file_id)">查看下单时商品图</button><view v-if="item.review" class="notice">已评价 {{ item.review.rating }} 星 · {{ item.review.content }}</view><view v-else-if="selected.status==='COMPLETED' && reviews[item.id]"><input v-model="reviews[item.id].rating" type="number" maxlength="1" placeholder="1 到 5 星"/><textarea v-model="reviews[item.id].content" maxlength="1000" placeholder="填写使用评价"/><button :disabled="busy" @click="review(item.id)">提交评价</button></view></view>
<text v-if="selected.cancellation_reason">取消原因：{{ selected.cancellation_reason }}</text><view v-if="selected.shipment" class="line"><text>承运方：{{ selected.shipment.carrier }}<br/>运单号：{{ selected.shipment.tracking_no }}</text><button class="secondary" @click="preview(selected.shipment.proof_file_id)">查看发货凭证</button></view>
<view v-if="['PENDING_CONFIRM','TO_SHIP'].includes(selected.status)"><input v-model="reason" maxlength="500" placeholder="取消原因（必填）"/><button :disabled="busy" @click="action('CANCEL')">取消订单</button></view><button v-if="selected.status==='SHIPPED'" :disabled="busy" @click="action('RECEIVE')">确认收货</button><text class="heading">订单轨迹</text><text v-for="(e,i) in selected.events" :key="i" class="notice">{{ orderTime(e.created_at) }} · {{ orderStatus(e.to_status) }} {{ e.reason }}</text></view>
<view v-else><text v-if="!busy && !orders.length" class="notice">还没有订单。可以从商品详情选择商家，提交模拟订单。</text><view v-for="o in orders" :key="o.id" class="card" @click="detail(o)"><text class="heading">{{ o.shop_name }} · {{ orderStatus(o.status) }}</text><text>{{ o.items.map(i=>i.product_name).join('、') }}</text><text>¥ {{ money(o.total_amount) }} · {{ orderTime(o.created_at) }}</text><text class="notice">查看详情 →</text></view><button v-if="orders.length<total" :disabled="busy" @click="run(()=>load(false))">加载更多</button></view>
</view></template>
<style scoped>
.screen{max-width:720px;margin:auto;padding:32rpx;min-height:100vh;background:#f7f5ee;color:#2c4238}.top{display:flex;align-items:center;justify-content:space-between}.title{font-size:40rpx;font-weight:700}.card{display:flex;flex-direction:column;gap:18rpx;background:#fff;padding:30rpx;margin:25rpx 0;border-radius:16rpx;font-size:25rpx;line-height:1.8;word-break:break-all}.heading{display:block;font-size:29rpx;font-weight:600}.notice{display:block;color:#7b866f;font-size:23rpx}.error{background:#fbece6;color:#a04436;padding:20rpx}.line{padding:20rpx 0;border-bottom:1px solid #eee;display:flex;flex-direction:column;gap:12rpx}button{background:#315745;color:white;border-radius:10rpx;font-size:25rpx;margin:14rpx 0}button::after{border:0}button.secondary{background:#e7ecdf;color:#315745}input,textarea{box-sizing:border-box;background:#f5f5ef;width:100%;padding:18rpx;font-size:26rpx;margin:14rpx 0}input{height:80rpx}textarea{height:160rpx}
</style>
